const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Jianghan District geometry (Wuhan, China)
  // Approximate bounding box for Jianghan District
  const jianghanGeometry = ee.Geometry.Rectangle([114.25, 30.55, 114.35, 30.65]);

  // 2. Load VIIRS Nighttime Lights monthly data
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1');

  // 3. Filter for January 2020
  const jan2020 = viirsCollection
    .filter(ee.Filter.date('2020-01-01', '2020-01-31'))
    .first();

  // 4. Filter for February 2020
  const feb2020 = viirsCollection
    .filter(ee.Filter.date('2020-02-01', '2020-02-29'))
    .first();

  // Check if both images exist
  const jan2020Exists = jan2020.getInfo() !== null;
  const feb2020Exists = feb2020.getInfo() !== null;

  if (!jan2020Exists || !feb2020Exists) {
    console.log('Jan 2020 exists:', jan2020Exists, 'Feb 2020 exists:', feb2020Exists);
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Extract average radiance for January 19, 2020 (using Jan 2020 composite)
  const jan2020Stats = jan2020
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: jianghanGeometry,
      scale: 1000,
      maxPixels: 1e9
    });

  const jan2020Value = jan2020Stats.get('avg_rad').getInfo();

  // 6. Extract average radiance for February 4, 2020 (using Feb 2020 composite)
  const feb2020Stats = feb2020
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: jianghanGeometry,
      scale: 1000,
      maxPixels: 1e9
    });

  const feb2020Value = feb2020Stats.get('avg_rad').getInfo();

  // 7. Validate results
  if (jan2020Value === null || jan2020Value === undefined || isNaN(jan2020Value)) {
    console.log('Jan 2020 value invalid:', jan2020Value);
    console.log('<answer>C3</answer>');
    return;
  }

  if (feb2020Value === null || feb2020Value === undefined || isNaN(feb2020Value)) {
    console.log('Feb 2020 value invalid:', feb2020Value);
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Check pixel counts to detect if valid pixels exist
  const janPixelCount = jan2020
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: jianghanGeometry,
      scale: 1000,
      maxPixels: 1e9
    })
    .get('avg_rad').getInfo();

  const febPixelCount = feb2020
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: jianghanGeometry,
      scale: 1000,
      maxPixels: 1e9
    })
    .get('avg_rad').getInfo();

  if (janPixelCount === 0 || febPixelCount === 0) {
    console.log('No valid pixels - Jan:', janPixelCount, 'Feb:', febPixelCount);
    console.log('<answer>C2</answer>');
    return;
  }

  // 9. Compare and output results
  console.log('Jan 2020 Radiance:', jan2020Value.toFixed(3), 'nW/cm²/sr (Pixels:', janPixelCount + ')');
  console.log('Feb 2020 Radiance:', feb2020Value.toFixed(3), 'nW/cm²/sr (Pixels:', febPixelCount + ')');

  // Check if February is lower than January
  if (feb2020Value < jan2020Value) {
    console.log('Feb 2020 is lower than Jan 2020');
    console.log('<answer>A</answer>');
  } else {
    console.log('Feb 2020 is not lower than Jan 2020');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
